# Let me find all complete rectangular boundaries of 0s
def find_complete_rectangular_0_frames(grid):
    h, w = len(grid), len(grid[0])
    frames = []

    # Iterate over possible top-left corners
    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] != 0:
                continue

            # Expand right along the first row to find frame width
            c2 = c1
            while c2 < w - 1 and grid[r1][c2 + 1] == 0:
                c2 += 1

            # Check if there's a closing border
            # We need at least 2 columns and 2 rows for a complete frame
            if c2 < c1 + 1:
                continue

            # Now check down the left column
            r2 = r1 + 1
            while r2 < h - 1 and grid[r2][c1] == 0:
                r2 += 1

            if r2 < r1 + 1:
                continue

            # Check bottom edge
            if not all(grid[r2][c] == 0 for c in range(c1, c2 + 1)):
                continue

            # Check right edge
            if not all(grid[r][c2] == 0 for r in range(r1, r2 + 1)):
                continue

            # Check top edge (already started but let's verify full)
            if not all(grid[r1][c] == 0 for c in range(c1, c2 + 1)):
                continue

            # Frame found! Check interior for 1s
            interior_ones = []
            for r in range(r1 + 1, r2):
                for c in range(c1 + 1, c2):
                    if grid[r][c] == 1:
