                    'top': r1, 'left': c1,
                    'bottom': r2, 'right': c2,
                    'height': r2 - r1 + 1, 'width': c2 - c1 + 1,
                    'interior_ones': interior_ones,
                    'interior_count': len(interior_ones)
                })

    return frames

